DO $$
DECLARE
  r RECORD;
  cur_status VARCHAR(20);
  cur_analyst INT;
BEGIN
  FOR r IN SELECT * FROM payment_events ORDER BY event_id LOOP
    SELECT status, assigned_analyst_id INTO cur_status, cur_analyst
    FROM installment_plans WHERE plan_id = r.plan_id;

    IF r.event_type = 1 AND cur_status = 'active' THEN
      UPDATE installment_plans
      SET status = 'under_review', assigned_analyst_id = r.analyst_id
      WHERE plan_id = r.plan_id;
    ELSIF r.event_type = 2 AND cur_status = 'under_review' AND cur_analyst = r.analyst_id THEN
      UPDATE installment_plans
      SET status = 'delinquent'
      WHERE plan_id = r.plan_id;
    ELSIF r.event_type = 3 AND cur_status = 'delinquent' THEN
      UPDATE installment_plans
      SET status = 'active', assigned_analyst_id = NULL
      WHERE plan_id = r.plan_id;
    ELSIF r.event_type = 4 AND cur_status = 'under_review' AND cur_analyst = r.old_analyst_id THEN
      UPDATE installment_plans
      SET assigned_analyst_id = r.new_analyst_id
      WHERE plan_id = r.plan_id;
    END IF;
  END LOOP;
END $$;

SELECT * FROM installment_plans ORDER BY plan_id;
